// ─────────────────────────────────────────────────────────────────────────
//  02 · violations to a 400★★☆
//  concepts: one problem body · grouped, sorted messages · never echo secrets
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** One constraint violation, as a validator reports it. */
    record Violation(String path, String message, Object invalidValue) {}

    /** The body of a 400 answer (RFC 9457 problem details, with an errors extension). */
    record Problem(int status, String title, String detail, Map<String, List<String>> errors, Map<String, String> rejected) {}

    static final Set<String> SECRET_WORDS = Set.of("password", "secret", "token", "cardnumber");

    static Problem toProblem(List<Violation> violations) {
        if (violations.isEmpty()) throw new IllegalArgumentException("no violations: nothing to report");
        var errors = new TreeMap<String, List<String>>();
        var rejected = new TreeMap<String, String>();
        for (var v : violations) {
            var messages = errors.computeIfAbsent(v.path(), k -> new ArrayList<>());
            if (!messages.contains(v.message())) messages.add(v.message());
            rejected.putIfAbsent(v.path(), isSecret(v.path()) ? "[redacted]" : String.valueOf(v.invalidValue()));
        }
        errors.replaceAll((k, list) -> list.stream().sorted().toList());
        int fields = errors.size();
        String detail = fields + (fields == 1 ? " field is" : " fields are") + " invalid";
        return new Problem(400, "Invalid request", detail, errors, rejected);
    }

    static boolean isSecret(String path) {
        String last = path.substring(path.lastIndexOf('.') + 1).replaceAll("\\[\\d+\\]$", "").toLowerCase(Locale.ROOT);
        return SECRET_WORDS.stream().anyMatch(last::contains);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("one field, one message", () -> {
            var p = toProblem(List.of(new Violation("email", "must be a well-formed email address", "ana@")));
            eq(p, new Problem(400, "Invalid request", "1 field is invalid", Map.of("email", List.of("must be a well-formed email address")), Map.of("email", "ana@")));
        });
        test("messages are grouped per field and sorted, fields in order", () -> {
            var p = toProblem(List.of(new Violation("name", "size must be between 2 and 40", "A"), new Violation("age", "must be at least 18", 12),
                                      new Violation("name", "must match \"[A-Za-z ]+\"", "A")));
            eq(List.of(new ArrayList<>(p.errors().keySet()), p.errors().get("name"), p.detail()),
               List.of(List.of("age", "name"), List.of("must match \"[A-Za-z ]+\"", "size must be between 2 and 40"), "2 fields are invalid"));
        });
        test("the same message twice for one field is reported once", () -> {
            var p = toProblem(List.of(new Violation("sku", "must not be blank", ""), new Violation("sku", "must not be blank", "")));
            eq(p.errors(), Map.of("sku", List.of("must not be blank")));
        });
        test("a secret field's value is never echoed back", () -> {
            var p = toProblem(List.of(new Violation("password", "size must be between 12 and 128", "hunter2"), new Violation("card.cardNumber", "invalid", "4111111111111111"),
                                      new Violation("passwordConfirmation", "must match password", "hunter3")));
            eq(p.rejected(), Map.of("password", "[redacted]", "card.cardNumber", "[redacted]", "passwordConfirmation", "[redacted]"));
        });
        test("a nested or indexed path is judged by its last name", () -> {
            var p = toProblem(List.of(new Violation("items[2].qty", "must be at least 1", 0), new Violation("tokens[0]", "must not be blank", "x")));
            eq(p.rejected(), Map.of("items[2].qty", "0", "tokens[0]", "[redacted]"));
        });
        test("a null invalid value is shown as null, and no violations is a bug (boundary)", () -> {
            eq(toProblem(List.of(new Violation("shipTo", "must not be null", null))).rejected(), Map.of("shipTo", "null"));
            raises(IllegalArgumentException.class, () -> toProblem(List.of()));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

fund-java/24-bean-validation-in-depth/02.explanation:
Group by path into sorted maps, keep each message once, and decide redaction from the path's last name:

```java
for (var v : violations) {
    var messages = errors.computeIfAbsent(v.path(), k -> new ArrayList<>());
    if (!messages.contains(v.message())) messages.add(v.message());
    rejected.putIfAbsent(v.path(), isSecret(v.path()) ? "[redacted]" : String.valueOf(v.invalidValue()));
}
```

`isSecret` takes the text after the last dot, strips a trailing `[i]`, lower-cases it and asks whether it contains a secret word. The tests catch the plausible wrong mappers. An exact lookup in the set instead of `contains` misses `passwordConfirmation` and `tokens[0]` (the secret and indexed-path tests). Comparing without lower-casing misses `cardNumber`, because the set holds `cardnumber`. Keeping duplicates reports "must not be blank" twice. Using a `HashMap` instead of a `TreeMap` gives an unstable field order (the grouping test checks `[age, name]`). Returning a 400 for an empty list hides a caller bug, so the boundary test expects an exception.

