    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.RECORD_COMPONENT) @interface NotNull {}
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.RECORD_COMPONENT) @interface NotBlank {}
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.RECORD_COMPONENT) @interface Size { int min() default 0; int max() default Integer.MAX_VALUE; }
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.RECORD_COMPONENT) @interface Min { long value(); }
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.RECORD_COMPONENT) @interface Valid {}

    record Item(@NotBlank String sku, @Min(1) int qty) {}
    record Address(@NotBlank String city, @Size(min = 4, max = 10) String postcode) {}
    record OrderRequest(@NotNull @Valid Address shipTo, @NotNull @Size(min = 1, max = 3) @Valid List<Item> items, @Size(max = 20) String note) {}

    /** Every violation of the record's constraints, as "path: message", sorted. */
    static List<String> validate(Record root) {
        var out = new TreeSet<String>();
        check(root, "", out);
        return List.copyOf(out);
    }

    static void check(Record bean, String prefix, Set<String> out) {
        for (RecordComponent rc : bean.getClass().getRecordComponents()) {
            Object value;
            try {
                value = rc.getAccessor().invoke(bean);
            } catch (ReflectiveOperationException e) {
                throw new IllegalStateException(e);
            }
            String path = prefix + rc.getName();
            if (rc.isAnnotationPresent(NotNull.class) && value == null) out.add(path + ": must not be null");
            if (rc.isAnnotationPresent(NotBlank.class) && (value == null || value.toString().isBlank())) out.add(path + ": must not be blank");
            Size size = rc.getAnnotation(Size.class);
            if (size != null && value != null) {
                int n = value instanceof Collection<?> c ? c.size() : value.toString().length();
                if (n < size.min() || n > size.max()) out.add(path + ": size must be between " + size.min() + " and " + size.max());
            }
            Min min = rc.getAnnotation(Min.class);
            if (min != null && value instanceof Number num && num.longValue() < min.value()) out.add(path + ": must be at least " + min.value());
            if (rc.isAnnotationPresent(Valid.class) && value != null) {
                if (value instanceof Record nested) check(nested, path + ".", out);
            }
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        var home = new Address("Lisbon", "1000-001");
        test("a valid request has no violations", () -> {
            eq(validate(new OrderRequest(home, List.of(new Item("tea", 2)), null)), List.of());
        });
        test("NotNull, NotBlank and Size report with the component name", () -> {
            eq(validate(new OrderRequest(null, null, "x".repeat(21))),
               List.of("items: must not be null", "note: size must be between 0 and 20", "shipTo: must not be null"));
        });
        test("null passes Size and Min: only NotNull and NotBlank reject a missing value", () -> {
            eq(validate(new OrderRequest(new Address("Porto", null), List.of(new Item("tea", 1)), null)), List.of());
        });
        test("a nested record marked @Valid is validated, with a dotted path", () -> {
            eq(validate(new OrderRequest(new Address("  ", "12"), List.of(new Item("tea", 1)), null)),
               List.of("shipTo.city: must not be blank", "shipTo.postcode: size must be between 4 and 10"));
        });
        test("each element of a @Valid list is validated, with its index in the path", () -> {
            eq(validate(new OrderRequest(home, List.of(new Item("tea", 1), new Item("", 0)), null)),
               List.of("items[1].qty: must be at least 1", "items[1].sku: must not be blank"));
        });
        test("Size on a list counts its elements; every violation is reported, sorted", () -> {
            var four = List.of(new Item("a", 1), new Item("b", 1), new Item("c", 1), new Item("", 1));
            eq(validate(new OrderRequest(new Address("", "1000-001"), four, null)),
               List.of("items: size must be between 1 and 3", "items[3].sku: must not be blank", "shipTo.city: must not be blank"));
        });
        test("an empty list breaks Size min, and a zero quantity breaks Min (boundary)", () -> {
            eq(List.of(validate(new OrderRequest(home, List.of(), null)), validate(new OrderRequest(home, List.of(new Item("tea", 0)), null))),
               List.of(List.of("items: size must be between 1 and 3"), List.of("items[0].qty: must be at least 1")));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

